DB_PATH = str(secret("DB_PATH", os.getenv("DB_PATH", "farm_ledger.sqlite3")))
COLUMNS = ["id", "date", "kind", "category", "crop", "amount", "memo"]
CATS = {"수입": ["농산물 판매", "보조금", "체험·가공", "기타 수입"], "지출": ["종자·종묘", "비료·농약", "인건비", "농기계·수리", "유류·전기", "임차료", "포장·운송", "기타 지출"]}
ADDRESS_BLOB = ''

def connect():
    con = sqlite3.connect(DB_PATH, timeout=20)
    con.execute("PRAGMA busy_timeout=20000")
    return con

with connect() as con:
    con.execute("""CREATE TABLE IF NOT EXISTS entries (
    id TEXT PRIMARY KEY, date TEXT NOT NULL, kind TEXT NOT NULL,
    category TEXT NOT NULL, crop TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), memo TEXT NOT NULL)""")

def read_entries():
    with connect() as con:
        return pd.read_sql_query("SELECT * FROM entries ORDER BY date DESC, rowid DESC", con)

def add_entry(day, kind, category, crop, amount, memo):
    with connect() as con:
        con.execute("INSERT INTO entries VALUES (?,?,?,?,?,?,?)", (uuid.uuid4().hex,day.isoformat(),kind,category,crop.strip(),int(amount),memo.strip()))

def won(value):
    return f"{int(value):,}원"

def csv_bytes(df):
    safe = df.copy()
    for col in ["category", "crop", "memo"]:
        safe[col] = safe[col].map(lambda x: "'"+x if isinstance(x,str) and x.startswith(("=","+","-","@","\t","\r")) else x)
    return safe.to_csv(index=False).encode("utf-8-sig")

def validate_import(upload):
    frame = pd.read_csv(upload, dtype=str, keep_default_na=False)
    if set(frame.columns) != set(COLUMNS):
        raise ValueError("이 앱에서 내려받은 전체 백업 CSV만 복원할 수 있습니다.")
    if len(frame)>50000:
        raise ValueError("한 번에 최대 50,000건까지 복원할 수 있습니다.")
    rows=[]
    for row in frame[COLUMNS].itertuples(index=False, name=None):
        ident, day, kind, category, crop, amount, memo=row
        if len(ident)!=32 or any(c not in "0123456789abcdef" for c in ident):
            raise ValueError("장부 ID 형식이 올바르지 않습니다.")
        if date.fromisoformat(day).isoformat()!=day or kind not in CATS:
            raise ValueError("날짜 또는 수입·지출 구분이 올바르지 않습니다.")
        if not amount.isdigit() or not 0<int(amount)<=100_000_000_000:
            raise ValueError("금액은 1원~1,000억원의 정수여야 합니다.")
        for name,value in [("항목",category),("작물",crop),("메모",memo)]:
            if len(value)>1000:
                raise ValueError(f"{name} 내용이 너무 깁니다.")
        category,crop,memo=[v[1:] if len(v)>1 and v[0]=="'" and v[1] in "=+-@\t\r" else v for v in (category,crop,memo)]
        if category not in CATS[kind]:
            raise ValueError("알 수 없는 장부 항목이 있습니다.")
        rows.append((ident,day,kind,category,crop,int(amount),memo))
    return rows

@st.cache_data(ttl=1800, show_spinner=False)
def weather(lat, lon):
    response=requests.get("https://api.open-meteo.com/v1/forecast",params={
        "latitude":lat,"longitude":lon,"daily":"weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,wind_speed_10m_max",
        "timezone":"Asia/Seoul","forecast_days":7},timeout=15)
    response.raise_for_status()
    return response.json(), datetime.now(ZoneInfo("Asia/Seoul")).strftime("%m.%d %H:%M")

def weather_label(code):
    if code==0:return "☀️ 맑음"
    if code in (1,2,3):return "⛅ 구름"
    if code in (45,48):return "🌫️ 안개"
    if code in (71,73,75,77,85,86):return "❄️ 눈"
    if code in (95,96,99):return "⛈️ 뇌우"
    if code in (51,53,55,56,57,61,63,65,66,67,80,81,82):return "🌧️ 비"
    return "🌤️ 예보 확인"

@st.cache_data(show_spinner=False)
def addresses():
    tree=json.loads(zlib.decompress(base64.b64decode(ADDRESS_BLOB)))
    for old,new in [("강원도","강원특별자치도"),("전라북도","전북특별자치도")]:
        if old in tree:tree[new]=tree.pop(old)
    return tree

@st.cache_data(show_spinner=False)
def address_index():
    rows=[]
    for province,p in addresses().items():
        for city,c in p.get("children",{}).items():
            for town,t in c.get("children",{}).items():
                try:rows.append((f"{province} {city} {town}",float(t["lat"]),float(t["lng"])))
                except (KeyError,ValueError,TypeError):continue
    return rows

@st.cache_data(ttl=86400,show_spinner=False)
def precise_address(query,key):
    r=requests.get("https://dapi.kakao.com/v2/local/search/address.json",headers={"Authorization":f"KakaoAK {key}"},params={"query":query,"size":10},timeout=15)
    r.raise_for_status()
    return [(x["address_name"],float(x["y"]),float(x["x"])) for x in r.json().get("documents",[]) if x.get("y") and x.get("x")]

def render_weather():
    with st.container(border=True):
        st.subheader("이번 주 우리 농장 날씨",anchor=False)
        if "farm_location" not in st.session_state:
            st.session_state.farm_location=None
        location=st.session_state.farm_location
        if location:st.write(location[0])
        with st.expander("농장 주소 찾기",expanded=location is None):
            mode=st.radio("주소 찾는 방법",["지역 순서로 찾기","주소 입력"],horizontal=True)
            candidate=None
            if mode=="지역 순서로 찾기":
                tree=addresses()
                province=st.selectbox("1. 시·도",sorted(tree),index=None,placeholder="시·도 선택")
                if province:
                    children=tree[province].get("children",{})
                    city=st.selectbox("2. 시·군·구",sorted(children),index=None,placeholder="시·군·구 선택",key="city_"+province)
                    if city:
                        towns=children[city].get("children",{})
                        town=st.selectbox("3. 읍·면·동",sorted(towns),index=None,placeholder="읍·면·동 선택",key="town_"+province+city)
                        if town:
                            t=towns[town]
                            candidate=(f"{province} {city} {town}",float(t["lat"]),float(t["lng"]))
            else:
                query=st.text_input("도로명·지번 또는 지역 이름",placeholder="예: 김제시 백산면 / 전주시 완산구 효자로 225")
                key=str(secret("KAKAO_REST_API_KEY",""))
                results=[]
                if len(query.strip())>=2:
                    if key:
                        try:results=precise_address(query.strip(),key)
                        except (requests.RequestException,KeyError,ValueError,TypeError):st.warning("주소 검색을 연결하지 못했습니다. 지역 순서로 찾아주세요.")
                    else:
                        tokens=query.strip().split()
                        results=[r for r in address_index() if all(t in r[0] for t in tokens)][:100]
                        st.caption("현재는 읍·면·동 이름으로 검색합니다. 도로명·번지 검색은 상세 주소 검색 연결 후 사용할 수 있습니다.")
                    if results:
                        candidate=st.selectbox("검색 결과",results,index=None,format_func=lambda x:x[0],placeholder="농장 주소 선택")
                    else:st.info("일치하는 주소가 없습니다. 시·군·구와 읍·면·동 이름으로 찾거나 지역 순서로 선택해주세요.")
            if candidate and st.button("이 위치의 날씨 보기",icon=":material/location_on:",use_container_width=True):
                st.session_state.farm_location=candidate
                st.rerun()
            st.caption("지역 선택은 읍·면·동 중심 위치 기준입니다. 일부 행정구역 개편은 반영되지 않을 수 있습니다.")
        location=st.session_state.farm_location
        if not location:
            st.info("농장 주소를 선택하면 오늘부터 7일 예보가 여기에 표시됩니다.")
            return
        if st.button("날씨 새로고침",icon=":material/refresh:"):weather.clear()
        try:
            data,updated=weather(location[1],location[2]);d=data["daily"]
            cards=[]
            weekday="월화수목금토일"
            for i,day in enumerate(d["time"]):
                dt=date.fromisoformat(day)
                label=weather_label(d["weather_code"][i]);parts=label.split(" ",1)
                symbol=parts[0];text=parts[-1]
                def fmt(value,unit=""):
                    return "—" if value is None else f"{value}{unit}"
                title="오늘" if i==0 else weekday[dt.weekday()]+"요일"
                cards.append(f'<div class="day-card {"today" if i==0 else ""}">{title}<br>{dt:%m.%d}<span class="weather-symbol">{symbol}</span>{text}<strong>{fmt(d["temperature_2m_min"][i])}° / {fmt(d["temperature_2m_max"][i])}°</strong>비 {fmt(d["precipitation_probability_max"][i],"%")}<br>{fmt(d["precipitation_sum"][i],"mm")}<br>바람 {fmt(d["wind_speed_10m_max"][i],"km/h")}</div>')
            st.markdown('<div class="week-grid">'+''.join(cards)+'</div>',unsafe_allow_html=True)
            st.caption("최저 / 최고 기온 · 오늘부터 7일 · "+updated+" 기준")
            if d["temperature_2m_min"][0] is not None and d["temperature_2m_min"][0]<=2:
                st.warning("오늘은 저온에 주의하세요. 보온·서리 피해 가능성을 확인하세요.")
            if (d["precipitation_probability_max"][0] or 0)>=60:
                st.info("비 가능성이 높습니다. 배수로와 야외작업 일정을 확인하세요.")
            if (d["wind_speed_10m_max"][0] or 0)>=25:
                st.warning("바람이 강할 수 있습니다. 시설물 고정 상태를 확인하세요.")
        except (requests.RequestException,KeyError,ValueError,TypeError,IndexError):
            st.warning("날씨를 불러오지 못했습니다. 잠시 후 다시 시도해주세요.")
        st.caption("작업 참고용 예보이며 공식 기상특보가 아닙니다.")
        st.markdown("예보 [Open-Meteo](https://open-meteo.com/) · [CC BY 4.0](https://creativecommons.org/licenses/by/4.0/) · 지역 정보 [KoreanAddressJson](https://github.com/Guk0/KoreanAddressJson)")

